CREATE FUNCTION Main() RETURNS BOOLEAN
	BEGIN
		CALL CopyEntireMessage();
		SET OutputRoot.JMSTransport.Transport_Folders.Header_Values.JMSPriority = 5;
		-- As part of MDM Upgrade added namespace --
		DECLARE NS12 NAMESPACE 'http://www.ibm.com/mdm/schema';
		IF process_obj_BU_shared.valid IS NULL THEN
			CALL RefreshCache();
		END IF;
		DECLARE cPreferredList CHARACTER '';
		SET Environment.Variables.PreferredBUList[] =SELECT ITEM (XREF.OBJ_TYPE_DESC) FROM process_obj_BU_shared.XREFData[] AS XREF ;

	--	DECLARE ns NAMESPACE 'http://www.ibm.com/mdm/schema';														
		DECLARE tcrmParm REFERENCE TO InputRoot.*[<].(XML.Element)[1].NS12:TCRMService.NS12:TCRMTx.NS12:TCRMObject.NS12:TCRMPartyIdentificationBObj[1];
		IF(POSITION(SUBSTRING(tcrmParm.NS12:IdentificationNumber from 1 for 3) IN Environment.Variables.PreferredBUList[1]) > 0)  THEN
			SET Environment.Variables.MPS = TRUE;
		END IF;

		IF FIELDNAME(InputRoot.*[<].(XML.Element)[1]) = 'DWLCompositeServiceRequest' AND Environment.Variables.MPS = TRUE THEN
			CREATE LASTCHILD OF OutputRoot.JMSTransport.Transport_Folders.Application_Properties NAME 'CompositeTxn' VALUE 'yes'; 
			CREATE LASTCHILD OF OutputRoot.JMSTransport.Transport_Folders.Application_Properties NAME 'CompositeParser' VALUE 'DWLService'; 
			CREATE LASTCHILD OF OutputRoot.JMSTransport.Transport_Folders.Application_Properties NAME 'CompositeConstructor' VALUE 'DWLService';  
		    PROPAGATE TO TERMINAL 'out1';
		    RETURN FALSE;	
		ELSEIF FIELDNAME(InputRoot.*[<].(XML.Element)[1]) = 'DWLCompositeServiceRequest' THEN
			CREATE LASTCHILD OF OutputRoot.JMSTransport.Transport_Folders.Application_Properties NAME 'CompositeTxn' VALUE 'yes'; 
			CREATE LASTCHILD OF OutputRoot.JMSTransport.Transport_Folders.Application_Properties NAME 'CompositeParser' VALUE 'DWLService'; 
			CREATE LASTCHILD OF OutputRoot.JMSTransport.Transport_Folders.Application_Properties NAME 'CompositeConstructor' VALUE 'DWLService';
			RETURN TRUE;
		END IF;

		RETURN TRUE;
	END;

CREATE FUNCTION Main() RETURNS BOOLEAN
	BEGIN
		SET OutputRoot.Properties = InputRoot.Properties;
		CREATE LASTCHILD OF OutputRoot DOMAIN 'MQMD';
		SET OutputRoot.XMLNSC.(XMLNSC.Folder)[1] = NULL;
		IF(EXISTS(InputRoot.XML[])) THEN
			CALL createMsgForMDMTracker('EMDM '|| COALESCE(InputRoot.XML.(XML.Element)[1].NS12:TCRMTx.NS12:TCRMTxType,'') ||' Request::'||COALESCE(CAST(ASBITSTREAM(InputRoot.XML CCSID 1208) AS CHARACTER CCSID 1208),''),OutputRoot.XMLNSC);
			SET OutputRoot.XMLNSC.dataroot.CreateTrackingEvent.OBJECT_ID = InputRoot.XML.(XML.Element)[1].NS12:RequestControl.NS12:requestID;
		ELSEIF(EXISTS(InputRoot.XMLNSC[])) THEN
			CALL createMsgForMDMTracker('EMDM '|| COALESCE(InputRoot.XMLNSC.(XMLNSC.Folder)[1].NS12:TCRMTx.NS12:TCRMTxType,'') ||' Request::'||COALESCE(CAST(ASBITSTREAM(InputRoot.XMLNSC CCSID 1208) AS CHARACTER CCSID 1208),''),OutputRoot.XMLNSC);
			SET OutputRoot.XMLNSC.dataroot.CreateTrackingEvent.OBJECT_ID = InputRoot.XMLNSC.(XMLNSC.Folder)[1].NS12:RequestControl.NS12:requestID;
		END IF;

		RETURN TRUE;
	END;
